-- Function used by computed columns (RemoveNonAlphaCharacters); created only when the database doesn't have it.
IF OBJECT_ID('dbo.RemoveNonAlphaCharacters') IS NULL
EXEC('CREATE Function [dbo].[RemoveNonAlphaCharacters](@Temp VarChar(max))
Returns VarChar(max)
AS
Begin

    Declare @KeepValues as varchar(50)
    Set @KeepValues = ''%[^a-z0-9]%''
    While PatIndex(@KeepValues, @Temp) > 0
        Set @Temp = Stuff(@Temp, PatIndex(@KeepValues, @Temp), 1, '''')

    Return @Temp
End
');
