IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.Web_Stock') AND name = 'IX_Input')
CREATE NONCLUSTERED INDEX [IX_Input] ON dbo.[Web_Stock] ([TrnType], [ItemID]) INCLUDE ([DocDate], [Qty], [Rate]) WHERE ([TrnType] IN ('IN', 'RET'));
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.Web_Stock') AND name = 'IX_Output')
CREATE NONCLUSTERED INDEX [IX_Output] ON dbo.[Web_Stock] ([TrnType], [ItemID]) INCLUDE ([DocDate], [Qty]) WHERE ([TrnType]='OUT');
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.Web_Stock') AND name = 'IX_Dave_General')
